vertexShader:
#include <fog_pars_vertex>
      varying vec3 vW; varying vec2 vUv;
      void main(){ vUv = uv; vec4 w = modelMatrix * vec4(position, 1.); vW = w.xyz; vec4 mvPosition = viewMatrix * w; gl_Position = projectionMatrix * mvPosition;
        #include <fog_vertex>
      }

fragmentShader:
#include <fog_pars_fragment>
      uniform float uTime, uFlash, uShore; uniform vec3 uSky; varying vec3 vW; varying vec2 vUv;
      float hh(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
      float rings(vec2 p, float s){ vec2 c = floor(p / s), f = fract(p / s) - .5; float r = 0.;
        for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) { vec2 o = vec2(float(x), float(y)), id = c + o; vec2 ctr = o + vec2(hh(id), hh(id + 7.)) - .5;
          float t = fract(uTime * (.7 + hh(id + 3.) * .6) + hh(id + 11.)), d = length(f - ctr) * s, R = t * .45 * s;
          r += (1. - smoothstep(0., .035, abs(d - R))) * (1. - t); }
        return r; }
      void main(){
        vec3 V = normalize(cameraPosition - vW); float fr = pow(1. - max(V.y, 0.), 4.);
        float rp = rings(vW.xz, 1.1) + rings(vW.xz + 13.7, .7) * .7;
        float wob = sin(atan(vUv.y - .5, vUv.x - .5) * 7. + vW.x * .3) * .025, edge = mix(1., smoothstep(.5, .36, length(vUv - .5) + wob), uShore);   // a ragged, soft shore
        float ns = hh(floor(vW.xz * .25)) * .5 + hh(floor(vW.xz * .07)) * .5;   // painted blotches of deeper and shallower water
        vec3 c = mix(vec3(.012, .03, .045), vec3(.025, .06, .07), ns) + uSky * (fr * .45 + rp * .14 + .03) + vec3(.7, .78, .95) * uFlash * (fr * .7 + .04 + rp * .25);
        gl_FragColor = vec4(c, edge * .92);
        #include <fog_fragment>
      }
